-- Train stations
create table stations (
    id varchar(10) primary key, -- Station identifier
    name varchar(30) not null, -- Station name
    num_platforms integer not null, -- Number of platforms in the station
    avg_weekday_passengers integer not null, -- Average number of daily passengers on a weekday
    avg_weekend_passengers integer not null, -- Average number of daily passengers on a weekend day
    owner varchar(10) not null -- Station owner
);

-- Services available at each station, and their opening days
create table station_services (
    station_id varchar(10) not null, -- Station identifier foreign key
    service varchar(100) not null, -- Description of the service
    open_mon boolean not null, -- Whether the service is open on monday
    open_tue boolean not null, -- Whether the service is open on tueday
    open_wed boolean not null, -- Whether the service is open on wednesday
    open_thu boolean not null, -- Whether the service is open on thursday
    open_fri boolean not null, -- Whether the service is open on friday
    open_sat boolean not null, -- Whether the service is open on saturday
    open_sun boolean not null, -- Whether the service is open on sunday
    constraint station_id
        foreign key (station_id) references stations (id)
        match simple on update cascade on delete cascade
);

-- A train route is a fixed path and train configuration
-- There are multiple trips on the same route within a day
create table train_routes (
    id varchar(30) primary key, -- Id of the route
    route_kind varchar(30) not null, -- Kind of route, e.g. 'InterRegio'
    bikes_permitted boolean not null, -- Whether bikes are permitted on this route
    carriages int not null -- Number of carriages in this train configuration
);
 
-- A train trip is a single one-way trip of a train on a route
create table train_trips (
    id varchar(40) primary key, -- Trip id
    route_id varchar(30) not null, -- Corresponding train_route
    headsign varchar(50) not null, -- Headsign on the train for this trip
    occupancy_1st_class int not null, -- Estimate of occupancy in 1st class, as an integer between 1 and 3 (inclusive)
    occupancy_2nd_class int not null, -- Estimate of occupancy in 2nd class, as an integer between 1 and 3 (inclusive)
    constraint route_id
        foreign key (route_id) references train_routes (id)
        match simple on update cascade on delete cascade
);

-- A customer's trip between two stations
create table customer_trips (
    id integer primary key, -- Customer trip id
    trip_id varchar(50) not null, -- Train trip corresponding to this customer trip
    board_station_id varchar(10) not null, -- Id of the station where the passenger boarded the train
    board_time timestamp not null, -- Time and date when the passenger boarded the train
    alight_station_id varchar(10) not null, -- Id of the station where the passenger alighted the train
    alight_time timestamp not null, -- Time and date when the passenger alighted the train
    stops integer not null, -- Number of stops encompassed by the customer's trip
    ticket_kind varchar(10) not null, -- Kind of ticket used for this trip, e.g. 'Day'
    duration_mins integer not null, -- Duration of the customer's trip in minutes
    constraint board_station_id
        foreign key (board_station_id) references stations (id)
        match simple on update cascade on delete cascade,
    constraint alight_station_id
        foreign key (alight_station_id) references stations (id)
        match simple on update cascade on delete cascade,
    constraint trip_id
        foreign key (trip_id) references train_trips (id)
        match simple on update cascade on delete cascade
);





